+package org.openjdk.bench.valhalla.array.copy;
+
+import jdk.internal.value.ValueClass;
+import org.openjdk.jmh.annotations.Benchmark;
+import org.openjdk.jmh.annotations.CompilerControl;
+import org.openjdk.jmh.annotations.Fork;
+import org.openjdk.jmh.annotations.Param;
+import org.openjdk.jmh.annotations.Setup;
+
+@Fork(value = 3, jvmArgsAppend = {
+    "--enable-preview",
+    "--add-exports", "java.base/jdk.internal.value=ALL-UNNAMED",
+    "-XX:+UnlockDiagnosticVMOptions",
+    "-XX:-UseArrayFlattening"
+})
+public class Value032NullFreePartialCopy extends CopyBase {
+
+    public interface InterfaceInt {
+        public int value();
+    }
+
+    public static value class ValueInt implements InterfaceInt {
+
+        public final int value;
+
+        public ValueInt(int value) {
+            this.value = value;
+        }
+
+        public int value() {
+            return value;
+        }
+    }
+
+    public static class ValState extends SizeState {
+        @Param({"2", "4", "6", "7", "8", "16", "32", "64", "256", "1024", "4096"})
+        public int size;
+
+        public ValueInt[] arr;
+
+        @Setup
+        public void setup() {
+        arr = (ValueInt[]) ValueClass.newNullRestrictedAtomicArray(ValueInt.class, size, new ValueInt(0));
+            for (int i = 0; i < size; i++) {
+                arr[i] = new ValueInt(i);
+            }
+        }
+    }
+
+    @CompilerControl(CompilerControl.Mode.DONT_INLINE)
+    public void arraycopy_partial(ValueInt[] src, int size) {
+        ValueInt[] dst = (ValueInt[]) ValueClass.newNullRestrictedAtomicArray(ValueInt.class, size, new ValueInt(0));
+        System.arraycopy(src, 0, dst, 0, size - 1);
+    }
+
+    @Benchmark
+    public void arraycopy_partial_val(ValState st) {
+        arraycopy_partial(st.arr, st.size);
+    }
+}
